Translate the following GNU C++11 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;
const int MAX_N = 10;

int a[MAX_N][MAX_N];

int add(int x, int y) {
    x += y;
    return x >= MOD ? x - MOD : x;
}

int sub(int x, int y) {
    x -= y;
    return x < 0 ? x + MOD : x;
}

int mul(int x, int y) {
    return (x * 1LL * y) % MOD;
}

int power(int x, int n) {
    if (n == 0) return 1;
    int y = power(x, n / 2);
    y = mul(y, y);
    return (n & 1) ? mul(y, x) : y;
}

int rev(int x) {
    return power(x, MOD - 2);
}

int divv(int x, int y) {
    return mul(x, rev(y));
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> a[i][j];
            a[i][j] = divv(a[i][j], 100);
        }

    vector<pair<vector<int>, int>> states, newStates;
    states.push_back({{0}, 1});

    for (int col = 0; col < n; ++col) {
        newStates.clear();
        for (int mask = 0; mask < (1 << n); ++mask) {
            int prob = 1;
            for (int row = 0; row < n; ++row) {
                if (mask & (1 << row))
                    prob = mul(prob, a[row][col]);
                else
                    prob = mul(prob, sub(1, a[row][col]));
            }
            for (auto &st : states) {
                vector<int> newVec;
                for (int m2 : st.first) {
                    int possible = (~m2) & mask;
                    while (possible) {
                        int bit = possible & -possible;
                        newVec.push_back(m2 | bit);
                        possible ^= bit;
                    }
                }
                if (newVec.empty()) continue;
                sort(newVec.begin(), newVec.end());
                newVec.erase(unique(newVec.begin(), newVec.end()), newVec.end());
                newStates.push_back({newVec, mul(st.second, prob)});
            }
        }
        sort(newStates.begin(), newStates.end());
        states.clear();
        int i = 0;
        while (i < (int)newStates.size()) {
            int j = i;
            int sumVal = 0;
            while (j < (int)newStates.size() && newStates[j].first == newStates[i].first) {
                sumVal = add(sumVal, newStates[j].second);
                ++j;
            }
            states.push_back({newStates[i].first, sumVal});
            i = j;
        }
    }

    int ans = 0;
    for (auto &st : states)
        ans = add(ans, st.second);
    cout << ans << "\n";
    return 0;
}
